<template><ContentWrap><h2>通知与运行状态</h2><el-button @click="load">刷新</el-button><el-descriptions border :column="2" style="margin-top:20px"><el-descriptions-item label="邮件服务">{{data.emailConfigured?'已配置':'未配置 SMTP'}}</el-descriptions-item><el-descriptions-item label="Web Push">{{data.pushConfigured?'密钥已配置；公网需 HTTPS':'未配置密钥'}}</el-descriptions-item><el-descriptions-item label="最近同步">{{data.lastSync||'尚无记录'}}</el-descriptions-item><el-descriptions-item label="成功检查次数">{{data.checks||0}}</el-descriptions-item></el-descriptions><el-alert title="SMTP 设置通过服务器环境文件配置；浏览器后台推送需要 HTTPS。本站不接管第三方订阅平台的用户数据。" type="info" :closable="false" style="margin:20px 0"/><h3>邮件投递记录（最近100条）</h3><el-table :data="data.deliveries"><el-table-column prop="id" label="ID"/><el-table-column prop="name" label="标题"/><el-table-column prop="status" label="状态"/><el-table-column prop="attempts" label="尝试次数"/><el-table-column prop="last_error" label="错误"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='FAILED'" v-hasPermi="['stock:notification:edit']" @click="retry(row.id,'email')">重试</el-button></template></el-table-column></el-table><h3>浏览器投递记录</h3><el-table :data="data.pushDeliveries"><el-table-column prop="id" label="ID"/><el-table-column prop="status" label="状态"/><el-table-column prop="last_error" label="错误"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='FAILED'" v-hasPermi="['stock:notification:edit']" @click="retry(row.id,'push')">重试</el-button></template></el-table-column></el-table><h3>浏览器订阅（最近100条）</h3><el-table :data="data.subscriptions"><el-table-column prop="id" label="ID"/><el-table-column prop="enabled" label="启用"/><el-table-column prop="create_time" label="订阅时间"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.enabled" v-hasPermi="['stock:notification:edit']" @click="remove(row.id)">停用</el-button></template></el-table-column></el-table></ContentWrap></template>
<script setup lang="ts">
import request from '@/config/axios'
const data=ref<any>({deliveries:[],pushDeliveries:[],subscriptions:[]})
async function load(){data.value=await request.get({url:'/stock/notification/status'})}
async function retry(id:number,type:string){await request.post({url:'/stock/notification/retry',params:{id,type}});load()}
async function remove(id:number){await request.delete({url:'/stock/notification/subscription',params:{id}});load()}
onMounted(load)
</script>